schemas.description:
Present value in the instrument's native currency.

This is the primary pricing output and is **always available** regardless
of which metrics are requested. The PV is **not** included in the `measures`
map - it is provided here as a `Money` type with full currency information.

For cross-currency instruments, this may be in a different currency than
the base calculation currency.

# Example
```rust
# use finstack_quant_valuations_core::results::ValuationResult;
# use finstack_quant_core::currency::Currency;
# use finstack_quant_core::money::Money;
# use finstack_quant_core::dates::create_date;
# use time::Month;
# fn main() -> Result<(), Box<dyn std::error::Error>> {
# let as_of = create_date(2025, Month::January, 15)?;
# let pv = Money::from((1_000_000_i64, Currency::USD));
# let result = ValuationResult::stamped("BOND-001", as_of, pv);
// PV is always in result.value, not in measures
let pv_money = result.value;  // Money type
let pv_amount = result.value.amount();  // f64 value
let currency = result.value.currency();  // Currency type
# Ok(())
# }
```

api.declaration:
/**
   * Describe canonical metric identifiers using Rust-owned units and coordinates.
   * @example
   * ```typescript
   * import init, { valuations } from "finstack-quant-wasm";
   * await init();
   * const [ytm, bucket] = valuations.instruments.metricMetadata([
   *   'ytm',
   *   'bucketed_dv01::USD-OIS::10y',
   * ]);
   * console.log(ytm.unit, bucket.components, bucket.bucketed);
   * ```
   * @param keys - Canonical scalar or qualified wire keys in output order. Custom keys retain unknown units; one the standard registry holds gets the group `"Instrument Specific"`, any other gets no group; malformed or obsolete encodings are rejected.
   * @returns Ordered metadata records preserving original keys, decoded components, the coordinates that order them, native unit families, display groups, and bucket eligibility.
   * @throws Error - Throws a validation error for malformed canonical metric keys or a serialization error when conversion fails.
   */
  metricMetadata(keys: string[]): MetricMetadata[];

/**
   * Get typed metadata for all built-in templates.
   * @returns Metadata objects in deterministic registry order.
   * @throws Error - Rejects if the embedded template registry cannot be parsed and validated, or if its metadata cannot be serialized to JSON.
   */
  listBuiltinTemplateMetadata(): TemplateMetadata[];

/**
   * Calculate portfolio margin requirements by netting set (Rust
   * `margin::portfolio_margin`).
   * @example
   * ```typescript
   * import init, { core, portfolio } from "finstack-quant-wasm";
   * await init();
   * const book = portfolio.Portfolio.builder("book", "USD", "2025-01-01").build();
   * const market = new core.MarketContext();
   * const margin = portfolio.portfolioMargin(book, market, "2025-01-01");
   * console.log(margin.total_initial_margin.amount, margin.netting_sets.length);
   * market.free();
   * book.free();
   * ```
   * @param portfolio - Built portfolio whose positions carrying margin metadata form the netting sets; its base currency is the reporting currency.
   * @param market - `core.MarketContext` handle supplying curves and quotes for VM and SIMM sensitivities, and the FX matrix for base-currency reporting.
   * @param asOf - ISO-8601 valuation date of the margin run.
   * @param currentImCollateral - Optional one-way IM balances already held, as an object (or JSON) keyed by CSA id with `Money` values (`{ amount, currency }`) in that CSA's currency. Omitted, `undefined`, `null` or a missing key means zero.
   * @returns The `PortfolioMarginResult` as a plain object.
   * @throws Error - Throws a `TypeError` (kind `invalid_type`) if `asOf` is not a string or `currentImCollateral` is not a JSON string or plain object, and a `FinstackError` if positions in one netting set carry conflicting margin specifications (kind `validation`), `asOf` is not an ISO date, `currentImCollateral` does not match the schema or names an unknown CSA id, or a required FX rate is unavailable.
   */
  portfolioMargin(
    portfolio: Portfolio,
    market: MarketContext,
    asOf: string,
    currentImCollateral?: Record<string, MoneyValue> | string | null
  ): PortfolioMarginResult;

/**
   * Transition probabilities as one row per starting state.
   * @returns An array of `number[]` rows in scale order.
   * @throws Error - Throws a `validation` error if the rows cannot be converted.
   */
  toRows(): number[][];

hostDeclarations.declaration:
/**
 * Valuation envelope returned by the `priceInstrument*` entry points (Rust `ValuationResult`).
 *
 * Generated from the host valuation-result schema: the 64-bit Monte Carlo
 * `seed` is a lossless `bigint` and path counts are plain numbers, so serialize
 * stochastic results with `valuations.valuationResultToJson` rather than
 * `JSON.stringify`. The emitted-field presence is stricter than the schema's
 * input view: `covenants` is always present (`null` when the instrument has
 * none), while `details`, `explanation` and `provenance` are omitted rather
 * than `null` when absent.
 * `provenance` is stamped on every priced result.
 */
export type ValuationResult = Omit<
  HostValuationResult,
  'covenants' | 'details' | 'explanation' | 'provenance'
> & {
  covenants: NonNullable<HostValuationResult['covenants']> | null;
  details?: NonNullable<HostValuationResult['details']>;
  explanation?: NonNullable<HostValuationResult['explanation']>;
  provenance?: NonNullable<HostValuationResult['provenance']>;
};

/**
 * Model-specific native detail, generated from Rust with exact host integer representations.
 */
export type ValuationDetails = import('./types/valuation-result.js').ValuationDetails;

/**
 * Convergence and reproducibility diagnostics for a Monte Carlo valuation.
 */
export type MonteCarloValuationDetails =
  import('./types/valuation-result.js').MonteCarloValuationDetails;

/**
 * Exact-decimal money `{amount, currency}` (Rust `Money` serde form): `amount` is a decimal string.
 *
 * Named `MoneyValue` in JavaScript because `Money` is the wasm-bindgen class.
 */
export type MoneyValue = generated.core.Money;

/**
 * Volatility smile generator for a fixed `(forward, t)` pair.
 *
 * Hagan SABR (2002): see docs/REFERENCES.md#hagan-2002-sabr.
 * @example
 * ```typescript
 * import init, { models } from "finstack-quant-wasm";
 * await init();
 * const params = models.volatility.SabrParameters.ratesDefault();
 * const smile = new models.volatility.SabrSmile(params, 0.03, 2);
 * console.log(smile.generateSmile([0.02, 0.03, 0.04]));
 * smile.free();
 * params.free();
 * ```
 */
export interface SabrSmileConstructor {
  /**
   * Create a SABR smile for a fixed forward and expiry.
   * @returns A `SabrSmile` handle for the supplied forward and expiry.
   * @param params - SABR parameter object containing alpha, beta, nu, rho, and optional shift.
   * @param forward - Forward price or rate in the same quote convention as the strike.
   * @param t - Time from the curve base date in years.
   */
  new (params: SabrParameters, forward: number, t: number): SabrSmile;
}
